ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate) {
  ssize_t count = 0;
  MagickBooleanType is_compressed = MagickFalse;
  CompressionType compression_type = next_image != (Image *) NULL ? next_image->compression : NoCompression;
  unsigned char *compact_pixels = (unsigned char *) NULL;
  size_t compact_length = 0;

  if (compression_type != NoCompression) {
    compact_pixels = AcquireCompactPixelPacket(next_image, &compact_length);
    if (compact_pixels == (unsigned char *) NULL)
      return 0;
  }

  for (ssize_t i = 0; i < (ssize_t) psd_info->number_channels; i++) {
    ChannelType channel = (ChannelType) i;
    if ((channel == IndexPixel) || ((channel != RedPixel) && (channel != GreenPixel) && (channel != BluePixel) && (channel != OpacityPixel)))
      continue;

    if (separate != MagickFalse) {
      if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
        count = 0;
        break;
      }
      continue;
    }

    if (image->storage_class == PseudoClass)
      continue;

    if (image->colorspace == CMYKColorspace) {
      if (channel == RedPixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
      else if (channel == GreenPixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
      else if (channel == BluePixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
      else if (channel == BlackPixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
    }
    else if ((image->colorspace == RGBColorspace) || (image->colorspace == GRAYColorspace)) {
      if (channel == RedPixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
      else if (channel == GreenPixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
      else if (channel == BluePixel) {
        if (WritePSDChannel(psd_info, image_info, image, channel, size_offset) == 0) {
          count = 0;
          break;
        }
      }
    }
  }

  if (compact_pixels != (unsigned char *) NULL)
    compact_pixels = (unsigned char *) RelinquishMemory(compact_pixels);

  return count;
}

ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info,
                         Image *image, Image *next_image,
                         MagickOffsetType size_offset, MagickBooleanType separate)
{
  ssize_t written_bytes = 0;
  MagickBooleanType is_compressed = MagickFalse;
  unsigned char *compact_pixels = NULL;
  size_t compact_length = 0;
  MagickOffsetType offset = size_offset;

  if (next_image != (Image *) NULL)
    is_compressed = (MagickBooleanType) (next_image->compression != NoCompression);

  if (is_compressed)
  {
    compact_pixels = AcquireCompactPixelInfo(image_info, image, &compact_length);
    if (compact_pixels == (unsigned char *) NULL)
      return 0;
  }

  switch (image->storage_class)
  {
    case DirectClass:
    {
      if (image->colorspace == RGBColorspace || image->colorspace == sRGBColorspace)
        written_bytes += WritePSDChannel(psd_info, image_info, image, "R", compact_pixels, compact_length, &offset, separate);
      written_bytes += WritePSDChannel(psd_info, image_info, image, "G", compact_pixels, compact_length, &offset, separate);
      written_bytes += WritePSDChannel(psd_info, image_info, image, "B", compact_pixels, compact_length, &offset, separate);
      if (image->alpha_trait != UndefinedAlpha)
        written_bytes += WritePSDChannel(psd_info, image_info, image, "A", compact_pixels, compact_length, &offset, separate);
      break;
    }

    case PseudoClass:
    {
      for (ssize_t i = 0; i < (ssize_t) image->colors; i++)
        written_bytes += WritePSDChannel(psd_info, image_info, image, "P", compact_pixels, compact_length, &offset, separate);
      break;
    }

    default:
      break;
  }

  if (image->mask != (Image *) NULL)
    written_bytes += WritePSDChannel(psd_info, image_info, image, "M", compact_pixels, compact_length, &offset, separate);

  if (compact_pixels != (unsigned char *) NULL)
    compact_pixels = RelinquishMagickMemory(compact_pixels);

  return written_bytes;
}

