ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate)
{
  MagickPixelPacket *compact_pixels = NULL;
  MagickOffsetType offset = 0;
  size_t number_pixels = 0;
  ssize_t bytes_written = 0;
  CompressionType compression;

  if (image == (Image *) NULL || image->pixels == (MagickPixelPacket *) NULL)
    return 0;

  compression = next_image->compression;

  if ((compression == JPEGCompression) || (compression == ZIPCompression))
  {
    compact_pixels = AcquireMagickPixelPackets(image, image->columns, image->rows);
    if (compact_pixels == (MagickPixelPacket *) NULL)
      return 0;
    CopyMagickPixelPackets(compact_pixels, image->pixels, image->columns, image->rows);
  }

  if (image->storage_class == DirectClass)
  {
    if (image->colorspace == RGBColorspace)
    {
      if (separate != MagickFalse)
      {
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 0, &offset);
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 1, &offset);
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 2, &offset);
      }
      else
      {
        bytes_written += WritePSDMultipleChannels(psd_info, image_info, image, &compact_pixels, &offset);
      }
    }
    else if (image->colorspace == CMYKColorspace)
    {
      if (separate != MagickFalse)
      {
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 0, &offset);
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 1, &offset);
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 2, &offset);
        bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 3, &offset);
      }
      else
      {
        bytes_written += WritePSDMultipleChannels(psd_info, image_info, image, &compact_pixels, &offset);
      }
    }
    else
    {
      bytes_written = 0;
    }

    if (image->mask != (Image *) NULL)
    {
      bytes_written += WritePSDChannel(psd_info, image_info, image, &compact_pixels, 3, &offset);
    }
  }

  if (compact_pixels != (MagickPixelPacket *) NULL)
    compact_pixels = RelinquishMagickPixelPackets(compact_pixels);

  if (bytes_written <= 0)
    return 0;

  return (ssize_t) offset;
}
